for e in items:
 if e['slug']not in aliases:
  name=re.sub(r'（[^）]*）|\([^)]*\)|[\u3400-\u9fff]','',e['name']).strip();aliases[e['slug']]=name if name.lower().startswith(e['brand'].lower())else e['brand']+' '+name
headers={'User-Agent':'CircuitMuseum/1.0 photo attribution discovery research'}
def get(host,params):
 req=urllib.request.Request(host+'/w/api.php?'+urllib.parse.urlencode(params),headers=headers)
 for attempt in range(4):
  try:return json.load(urllib.request.urlopen(req,timeout=40))
  except urllib.error.HTTPError as e:
   if e.code!=429 or attempt==3:raise
   time.sleep(max(int(e.headers.get('Retry-After','9')),9))
output=root/'docs/evidence/photo-expansion';found={}
for start in range(0,len(items),45):
 group=items[start:start+45];data=get('https://en.wikipedia.org',{'action':'query','format':'json','titles':'|'.join(aliases[e['slug']]for e in group),'redirects':1,'prop':'pageimages','piprop':'name'})
 redirects={r['from']:r['to']for r in data.get('query',{}).get('redirects',[])};normal={r['from']:r['to']for r in data.get('query',{}).get('normalized',[])}
 pages={p['title']:p for p in data.get('query',{}).get('pages',{}).values()}
 for e in group:
  title=normal.get(aliases[e['slug']],aliases[e['slug']]);title=redirects.get(title,title);p=pages.get(title,{})
  found[e['slug']]={'slug':e['slug'],'article':p.get('title',title),'filename':p.get('pageimage'),'status':'discovery-only-not-model-or-license-approval'}
 time.sleep(9)
(output/'wiki-file-discovery.json').write_text(json.dumps(list(found.values()),ensure_ascii=False,indent=2)+'\n')
print('Found public filename hints',sum(bool(e['filename'])for e in found.values()))
